select po.id, pod.id as purchaseDetailId, po.type as type, po.code, pos.supplier_name as supplierName, po.approve_status as approveStatus, po.invalid_status as invalidStatus, pod.arrival_status as arrivalStatus, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.variant_property as variantProperty, pod.plan_delivery_date as planDeliveryDate, pod.is_urgent as isUrgent, po.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency_symbol, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, po.subcontract_type as subcontractType, po.approve_user_name as approveUserName, po.approve_time as approveTime, po.purchase_user_name as purchaseUserName, po.create_user_name as createUserName, po.create_time as createTime, pod.is_end_receive as isEndReceive, so.code as subContractCode, po.source_id as sourceId, po.source_type as sourceType from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order so on so.id = po.source_id and so.is_deleted = false
po.is_deleted = false
and pod.product_name ILIKE concat('%',#{params.productName}::text,'%')
and po.code ILIKE concat('%',#{params.code}::text,'%')
and so.code ILIKE concat('%',#{params.subContractCode}::text,'%')
and case when subString(#{params.sourceCode},1,2) != 'PL' then po.source_code ILIKE concat('%',#{params.sourceCode}::text,'%') else EXISTS ( select pa.id from purchase_application pa left join purchase_application_ref_po parp on parp.is_deleted = false and pa.id = parp.purchase_application_id where parp.purchase_order_id = po.id and pa.code ILIKE concat('%',#{params.sourceCode}::text,'%') ) end
and pod.is_urgent = #{params.isUrgent}
and po.invalid_status = #{params.invalidStatus}
and po.is_first_mass_product = #{params.isFirstMassProduct}
and po.type in
#{item}
