select po.code, s.name as supplierName, po.approve_status as approveStatus, pod.sku_id as skuId, pod.sku_no as skuNo, pod.plan_delivery_date as planDeliveryDate, po.delivery_warehouse_name as deliveryWarehouseName, po.purchase_user_name as purchaseUserName, so.code as subContractCode from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false inner join subcontract_order_detail sod on pod.source_detail_id = sod.id and sod.is_deleted = false inner join subcontract_order so on so.id = sod.main_id and so.is_deleted = false left join supplier s on sod.supplier_id = s.id and s.is_deleted = false
po.is_deleted = false and po.invalid_status = false
and sod.main_id = #{sourceId}

SELECT T.sku_id as skuId, T."sku_no" AS skuNo, T."LatestPurchaseDate" AS costDate, D.tax_price as costPrice, D.tax_price/( 1 + D.tax_rate) as notTaxCostPrice, D.purchase_qty as qty, D.currency, CAST(T."LatestPurchaseDate" - INTERVAL '3 months' AS DATE) AS threeMonthsAgoDate, CAST(T."LatestPurchaseDate" AS DATE) AS latestPurchaseDate FROM ( SELECT pod.sku_id, pod.sku_no, MAX(po.purchase_date) AS "LatestPurchaseDate" FROM purchase_order po LEFT JOIN purchase_order_detail pod ON po.id = pod.purchase_order_id AND pod.is_deleted = FALSE WHERE po.is_deleted = FALSE and po.type = 'CGDD01_SYS' and po.invalid_status = false and po.approve_status = 'approve'
AND pod.sku_id in
#{item}
AND pod.sku_no in
#{item}
GROUP BY pod.sku_no ,pod.sku_id ) AS T JOIN purchase_order S LEFT JOIN purchase_order_detail D ON S.id = D.purchase_order_id AND D.is_deleted = FALSE ON T."sku_no" = D."sku_no" AND S."purchase_date" >= T."LatestPurchaseDate" - INTERVAL '3 months' WHERE S.is_deleted = false and S.type = 'CGDD01_SYS' and S.invalid_status = false and S.approve_status = 'approve'
